<template><div class="app-container"><el-button v-if="mode==='apply'" type="primary" @click="edit()">申请加入企业</el-button><el-button @click="load">刷新</el-button>
<el-table v-loading="loading" :data="rows"><el-table-column prop="real_name" label="姓名"/><el-table-column prop="company_id" label="企业编号"/><el-table-column prop="employee_no" label="工号"/><el-table-column prop="contact_phone" label="联系电话"/><el-table-column prop="job_title" label="岗位"/><el-table-column label="状态"><template #default="{row}">{{states[row.status]||row.status}}</template></el-table-column><el-table-column label="操作" width="320"><template #default="{row}"><el-button link @click="view(row)">详情</el-button><el-button v-if="mode==='profile'||mode==='manage'||mode==='apply'&&['DRAFT','REJECTED'].includes(row.status)" link @click="edit(row)">修改</el-button><el-button v-if="mode==='apply'&&['DRAFT','REJECTED'].includes(row.status)" link type="primary" @click="submit(row)">提交</el-button><el-button v-if="mode==='review'&&row.status==='PENDING'" link type="primary" @click="review(row)">审核</el-button><el-button v-if="mode==='manage'" v-hasPermi="['biz:employee:roles']" link @click="grant(row)">分配角色</el-button></template></el-table-column></el-table>
<el-dialog v-model="visible" title="员工资料" width="540px"><el-form label-width="100px"><el-form-item v-if="mode==='apply'" label="所属企业"><el-select v-model="form.companyId" :disabled="!!form.id" filterable><el-option v-for="c in companies" :key="c.id" :label="c.company_name" :value="c.id"/></el-select></el-form-item><el-form-item label="姓名"><el-input v-model="form.realName" maxlength="50"/></el-form-item><el-form-item label="联系电话"><el-input v-model="form.contactPhone" maxlength="30"/></el-form-item><el-form-item v-if="mode!=='profile'" label="岗位"><el-input v-model="form.jobTitle" maxlength="80"/></el-form-item><el-form-item v-if="mode==='manage'" label="工号"><el-input v-model="form.employeeNo" maxlength="40"/></el-form-item></el-form><template #footer><el-button :loading="saving" type="primary" @click="save">保存</el-button></template></el-dialog>
<el-dialog v-model="detailsVisible" title="员工详情"><el-descriptions :column="1" border><el-descriptions-item v-for="(label,key) in labels" :key="key" :label="label">{{detail[key]}}</el-descriptions-item></el-descriptions><el-table :data="detail.audits||[]"><el-table-column prop="round_no" label="轮次"/><el-table-column prop="opinion" label="审核意见"/><el-table-column prop="to_status" label="结果"/></el-table></el-dialog>
<el-dialog v-model="reviewVisible" title="员工入驻审核"><el-radio-group v-model="decision.approve"><el-radio :value="true">通过</el-radio><el-radio :value="false">驳回</el-radio></el-radio-group><el-input v-model="decision.opinion" type="textarea" maxlength="500" placeholder="审核意见必填"/><template #footer><el-button type="primary" :loading="saving" @click="decide">确认</el-button></template></el-dialog>
<el-dialog v-model="rolesVisible" title="分配企业业务角色"><el-checkbox-group v-model="assigned"><el-checkbox value="employee">普通员工</el-checkbox><el-checkbox value="company_hr">企业人事</el-checkbox><el-checkbox value="company_business">企业业务</el-checkbox><el-checkbox value="company_finance">企业财务</el-checkbox></el-checkbox-group><p>保存后以本次选择替换业务角色，普通员工角色始终保留，员工需要重新登录。</p><template #footer><el-button type="primary" :loading="saving" @click="saveRoles">保存</el-button></template></el-dialog>
</div></template>
<script setup>
import {ref,computed,watch} from 'vue'
import {useRoute} from 'vue-router'
import {ElMessage,ElMessageBox} from 'element-plus'
import request from '@/utils/request'
const route=useRoute(),mode=computed(()=>route.path.endsWith('employee-review')?'review':route.path.endsWith('employee-profile')?'profile':route.path.endsWith('/employees')?'manage':'apply')
const rows=ref([]),companies=ref([]),loading=ref(false),saving=ref(false),visible=ref(false),detailsVisible=ref(false),reviewVisible=ref(false),rolesVisible=ref(false),form=ref({}),detail=ref({}),decision=ref({}),assigned=ref(['employee']),target=ref()
const states={DRAFT:'草稿',PENDING:'待审核',APPROVED:'已通过',REJECTED:'已驳回',ACTIVE:'在职',LEFT:'离职'}
const labels={real_name:'姓名',company_id:'企业编号',contact_phone:'联系电话',employee_no:'工号',job_title:'岗位',status:'状态'}
async function load(){loading.value=true;try{const path=mode.value==='manage'?'staff':mode.value==='profile'?'me':'applications';const r=await request({url:'/employees/'+path,params:{review:mode.value==='review'}});rows.value=mode.value==='profile'?[r.data]:r.data;if(mode.value==='apply')companies.value=(await request({url:'/employees/companies'})).data}finally{loading.value=false}}
function edit(row){form.value=row?{id:row.id,companyId:row.company_id,realName:row.real_name,contactPhone:row.contact_phone,jobTitle:row.job_title,employeeNo:row.employee_no,version:row.version}:{};visible.value=true}
async function save(){saving.value=true;try{const path=mode.value==='manage'?'staff':mode.value==='profile'?'me':'applications';await request({url:'/employees/'+path+(form.value.id?'/'+form.value.id:''),method:form.value.id?'put':'post',data:form.value});visible.value=false;ElMessage.success('保存成功');await load()}finally{saving.value=false}}
async function submit(row){await ElMessageBox.confirm('确认提交员工入驻申请？');await request({url:`/employees/applications/${row.id}/submit`,method:'post'});await load()}
async function view(row){detail.value=['apply','review'].includes(mode.value)?(await request({url:'/employees/applications/'+row.id})).data:mode.value==='manage'?(await request({url:'/employees/staff/'+row.id})).data:row;detailsVisible.value=true}
function review(row){decision.value={id:row.id,approve:true,opinion:''};reviewVisible.value=true}
async function decide(){if(!decision.value.opinion?.trim()){ElMessage.warning('请填写意见');return}saving.value=true;try{await request({url:`/employees/applications/${decision.value.id}/review`,method:'post',data:decision.value});reviewVisible.value=false;ElMessage.success('审核完成，通过后员工需重新登录');await load()}finally{saving.value=false}}
function grant(row){target.value=row.id;assigned.value=['employee'];rolesVisible.value=true}
async function saveRoles(){saving.value=true;try{await request({url:`/employees/staff/${target.value}/roles`,method:'put',data:assigned.value});rolesVisible.value=false;ElMessage.success('角色已更新，员工需重新登录')}finally{saving.value=false}}
watch(mode,()=>{rows.value=[];visible.value=false;detailsVisible.value=false;reviewVisible.value=false;rolesVisible.value=false;load()},{immediate:true})
</script>
